(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // ── State ──────────────────────────────────────────────────────────

  var todos = [];
  var filter = 'all';
  var editingId = null;

  // ── DOM references ─────────────────────────────────────────────────

  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var mainSection = document.querySelector('.main');
  var footerSection = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var toggleAll = document.querySelector('.toggle-all');
  var filterLinks = document.querySelectorAll('.filters a');

  // ── Storage ────────────────────────────────────────────────────────

  function loadTodos() {
    var stored;
    try {
      stored = localStorage.getItem(STORAGE_KEY);
    } catch (e) {}
    if (stored) {
      try {
        todos = JSON.parse(stored);
      } catch (e) {
        todos = [];
      }
    } else {
      todos = [];
    }
  }

  function saveTodos() {
    var toStore = [];
    for (var i = 0; i < todos.length; i++) {
      toStore.push({
        id: todos[i].id,
        title: todos[i].title,
        completed: todos[i].completed
      });
    }
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(toStore));
    } catch (e) {}
  }

  // ── Helpers ────────────────────────────────────────────────────────

  function uid() {
    return Date.now() + Math.random().toString(36).slice(2, 8);
  }

  function getFilteredTodos() {
    if (filter === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (filter === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  function getActiveCount() {
    var count = 0;
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) count++;
    }
    return count;
  }

  function getCompletedCount() {
    var count = 0;
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].completed) count++;
    }
    return count;
  }

  function pluralize(count, word) {
    return count === 1 ? word : word + 's';
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // ── Render ─────────────────────────────────────────────────────────

  function render() {
    var filtered = getFilteredTodos();
    var html = '';
    for (var i = 0; i < filtered.length; i++) {
      var todo = filtered[i];
      var isCompleted = todo.completed ? 'completed' : '';
      var isEditing = todo.id === editingId ? 'editing' : '';
      var checkedAttr = todo.completed ? 'checked' : '';
      html += '<li class="' + isCompleted + ' ' + isEditing + '" data-id="' + todo.id + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox" ' + checkedAttr + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    // Main and footer visibility
    var hasTodos = todos.length > 0;
    mainSection.style.display = hasTodos ? 'block' : 'none';
    footerSection.style.display = hasTodos ? 'block' : 'none';

    // Count
    var activeCount = getActiveCount();
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralize(activeCount, 'item') + ' left';

    // Clear completed visibility
    var hasCompleted = getCompletedCount() > 0;
    clearCompletedBtn.style.display = hasCompleted ? 'block' : 'none';

    // Toggle-all state
    var allCompleted = hasTodos && activeCount === 0;
    toggleAll.checked = allCompleted;

    // Filter links
    for (var j = 0; j < filterLinks.length; j++) {
      var link = filterLinks[j];
      var href = link.getAttribute('href');
      var linkFilter = 'all';
      if (href === '#/active') linkFilter = 'active';
      else if (href === '#/completed') linkFilter = 'completed';
      if (linkFilter === filter) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    }

    // If editing, focus the edit input
    if (editingId !== null) {
      var editInput = todoList.querySelector('li.editing .edit');
      if (editInput) {
        editInput.focus();
        // Put cursor at end
        var len = editInput.value.length;
        if (editInput.setSelectionRange) {
          editInput.setSelectionRange(len, len);
        }
      }
    }
  }

  // ── Actions ────────────────────────────────────────────────────────

  function addTodo(title) {
    title = title.trim();
    if (title === '') return;
    todos.push({
      id: uid(),
      title: title,
      completed: false
    });
    saveTodos();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    saveTodos();
    render();
  }

  function destroyTodo(id) {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id !== id) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    if (editingId === id) editingId = null;
    saveTodos();
    render();
  }

  function editTodo(id) {
    editingId = id;
    render();
  }

  function saveEdit(id, title) {
    title = title.trim();
    if (title === '') {
      destroyTodo(id);
    } else {
      for (var i = 0; i < todos.length; i++) {
        if (todos[i].id === id) {
          todos[i].title = title;
          break;
        }
      }
      editingId = null;
      saveTodos();
      render();
    }
  }

  function cancelEdit() {
    editingId = null;
    render();
  }

  function clearCompleted() {
    var newTodos = [];
    for (var i = 0; i < todos.length; i++) {
      if (!todos[i].completed) {
        newTodos.push(todos[i]);
      }
    }
    todos = newTodos;
    saveTodos();
    render();
  }

  function toggleAllTodos() {
    var activeCount = getActiveCount();
    var allCompleted = activeCount === 0;
    for (var i = 0; i < todos.length; i++) {
      todos[i].completed = !allCompleted;
    }
    saveTodos();
    render();
  }

  function setFilter(newFilter) {
    filter = newFilter;
    render();
  }

  // ── Router ─────────────────────────────────────────────────────────

  function handleRoute() {
    var hash = window.location.hash;
    if (hash === '#/active') {
      setFilter('active');
    } else if (hash === '#/completed') {
      setFilter('completed');
    } else {
      setFilter('all');
    }
  }

  // ── Event Handlers ─────────────────────────────────────────────────

  function onNewTodoKeydown(e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  }

  function onTodoListClick(e) {
    var target = e.target;
    var li = target.closest ? target.closest('li') : null;
    if (!li) return;
    var id = li.getAttribute('data-id');

    if (target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (target.classList.contains('destroy')) {
      destroyTodo(id);
    }
  }

  function onTodoListDblclick(e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var li = target.closest ? target.closest('li') : null;
      if (li) {
        editTodo(li.getAttribute('data-id'));
      }
    }
  }

  function onTodoListChange(e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      var li = target.closest ? target.closest('li') : null;
      if (li) {
        saveEdit(li.getAttribute('data-id'), target.value);
      }
    }
  }

  function onTodoListKeydown(e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      if (e.keyCode === ENTER_KEY) {
        e.preventDefault();
        var li = target.closest ? target.closest('li') : null;
        if (li) {
          saveEdit(li.getAttribute('data-id'), target.value);
        }
      } else if (e.keyCode === ESCAPE_KEY) {
        cancelEdit();
      }
    }
  }

  function onTodoListBlur(e) {
    var target = e.target;
    if (target.classList.contains('edit')) {
      if (editingId !== null) {
        var li = target.closest ? target.closest('li') : null;
        if (li) {
          saveEdit(li.getAttribute('data-id'), target.value);
        }
      }
    }
  }

  function onToggleAllChange(e) {
    toggleAllTodos();
  }

  function onClearCompletedClick() {
    clearCompleted();
  }

  function onHashChange() {
    handleRoute();
  }

  // ── Init ───────────────────────────────────────────────────────────

  function init() {
    loadTodos();
    handleRoute();
    render();

    // Bind events
    newTodoInput.addEventListener('keydown', onNewTodoKeydown);
    todoList.addEventListener('click', onTodoListClick);
    todoList.addEventListener('dblclick', onTodoListDblclick);
    todoList.addEventListener('change', onTodoListChange);
    todoList.addEventListener('keydown', onTodoListKeydown);
    todoList.addEventListener('blur', onTodoListBlur, true);
    toggleAll.addEventListener('change', onToggleAllChange);
    clearCompletedBtn.addEventListener('click', onClearCompletedClick);
    window.addEventListener('hashchange', onHashChange);
  }

  // Handle both DOMContentLoaded and direct execution
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');
const STORAGE_KEY = 'todos-vanillajs';

// ── Helpers ──────────────────────────────────────────────────────────

function qs(selector) {
  return this.document.querySelector(selector);
}

function qsa(selector) {
  return this.document.querySelectorAll(selector);
}

function findTodoItem(label) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const lbl = li.querySelector('label');
    if (lbl && lbl.textContent.trim() === label) return li;
  }
  return null;
}

function addTodoViaApp(title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const event = new this.window.Event('change', { bubbles: true });
  input.dispatchEvent(event);
  const keydown = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  input.dispatchEvent(keydown);
}

function completeTodoViaApp(label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const toggle = li.querySelector('.toggle');
  toggle.click();
}

function loadAppAtUrl(url) {
  const indexPath = path.join(ROOT, 'index.html');
  const appPath = path.join(ROOT, 'js', 'app.js');
  const appSource = fs.readFileSync(appPath, 'utf8');
  const win = new Window({
    url: url,
    settings: { disableJavaScriptFileLoading: true },
  });
  const doc = win.document;
  doc.write(fs.readFileSync(indexPath, 'utf8'));
  doc.close();
  win.eval(appSource);
  doc.dispatchEvent(new win.Event('DOMContentLoaded', { bubbles: true }));
  win.dispatchEvent(new win.Event('load'));
  return { window: win, document: doc };
}

// ── Given steps ──────────────────────────────────────────────────────

Given('the app is loaded', function () {
  // Already loaded by Before hook in world.js
});

Given('there is a todo {string}', function (title) {
  addTodoViaApp.call(this, title);
});

Given('there is a completed todo {string}', function (title) {
  addTodoViaApp.call(this, title);
  const li = findTodoItem.call(this, title);
  if (!li) throw new Error(`Todo "${title}" not found after adding`);
  const toggle = li.querySelector('.toggle');
  toggle.click();
});

Given('there are todos:', function (dataTable) {
  const rows = dataTable.rows();
  for (const [title, completed] of rows) {
    addTodoViaApp.call(this, title);
    if (completed === 'true') {
      const li = findTodoItem.call(this, title);
      if (!li) throw new Error(`Todo "${title}" not found`);
      li.querySelector('.toggle').click();
    }
  }
});

Given('the app is loaded with a todo {string} already stored', function (title) {
  const { window: win, document: doc } = loadAppAtUrl('http://localhost/');
  // Seed localStorage before the app reads it
  win.localStorage.setItem(STORAGE_KEY, JSON.stringify([
    { id: Date.now(), title: title, completed: false }
  ]));
  // Reload the app (eval again after localStorage is seeded)
  const appPath = path.join(ROOT, 'js', 'app.js');
  const appSource = fs.readFileSync(appPath, 'utf8');
  win.eval(appSource);
  doc.dispatchEvent(new win.Event('DOMContentLoaded', { bubbles: true }));
  win.dispatchEvent(new win.Event('load'));
  // Replace the scenario's window/document
  const old = this.window;
  this.window = win;
  this.document = doc;
  if (old && old.happyDOM && typeof old.happyDOM.close === 'function') {
    // dispose old window in background
  }
});

Given('the app is loaded with the {string} hash', function (hash) {
  const { window: win, document: doc } = loadAppAtUrl('http://localhost' + hash);
  const old = this.window;
  this.window = win;
  this.document = doc;
});

// ── When steps ───────────────────────────────────────────────────────

When('I enter {string} in the new todo input and press Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  const event = new this.window.Event('change', { bubbles: true });
  input.dispatchEvent(event);
  const keydown = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  input.dispatchEvent(keydown);
});

When('I click the checkbox next to {string}', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const toggle = li.querySelector('.toggle');
  toggle.click();
});

When('I double-click {string} to edit', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  const lbl = li.querySelector('label');
  const dblClick = new this.window.MouseEvent('dblclick', {
    bubbles: true,
    detail: 2,
  });
  lbl.dispatchEvent(dblClick);
});

When('I change the title to {string} and press Enter', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo is being edited');
  editInput.value = newTitle;
  const keydown = new this.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true,
  });
  editInput.dispatchEvent(keydown);
});

When('I change the title to {string} and blur the edit input', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo is being edited');
  editInput.value = newTitle;
  const blur = new this.window.FocusEvent('blur', { bubbles: true });
  editInput.dispatchEvent(blur);
});

When('I press Escape while editing', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No todo is being edited');
  const keydown = new this.window.KeyboardEvent('keydown', {
    key: 'Escape',
    keyCode: 27,
    which: 27,
    bubbles: true,
  });
  editInput.dispatchEvent(keydown);
});

When('I click "Clear completed"', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('Clear completed button not found');
  btn.click();
});

When('I click the toggle-all checkbox', function () {
  const toggle = this.document.querySelector('.toggle-all');
  if (!toggle) throw new Error('Toggle-all checkbox not found');
  toggle.click();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

// ── Then steps ───────────────────────────────────────────────────────

Then('I should see {string} in the todo list', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Expected "${label}" in todo list, but it was not found`);
});

Then('I should not see {string} in the todo list', function (label) {
  const li = findTodoItem.call(this, label);
  if (li) throw new Error(`Expected "${label}" to NOT be in todo list, but it was found`);
});

Then('the new todo input should be cleared', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') {
    throw new Error(`Expected new todo input to be empty, but got "${input.value}"`);
  }
});

Then('the todo list should be empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length > 0) {
    throw new Error(`Expected empty todo list, but found ${items.length} items`);
  }
});

Then('the main section should be visible', function () {
  const main = this.document.querySelector('.main');
  if (!main || main.style.display === 'none' || main.hidden) {
    throw new Error('Expected main section to be visible');
  }
});

Then('the main section should not be visible', function () {
  const main = this.document.querySelector('.main');
  if (main && main.style.display !== 'none' && !main.hidden) {
    throw new Error('Expected main section to be hidden');
  }
});

Then('the footer section should be visible', function () {
  const footer = this.document.querySelector('.footer');
  if (!footer || footer.style.display === 'none' || footer.hidden) {
    throw new Error('Expected footer section to be visible');
  }
});

Then('the footer section should not be visible', function () {
  const footer = this.document.querySelector('.footer');
  if (footer && footer.style.display !== 'none' && !footer.hidden) {
    throw new Error('Expected footer section to be hidden');
  }
});

Then('{string} should be marked as completed', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  if (!li.classList.contains('completed')) {
    throw new Error(`Expected "${label}" to be completed, but it was not`);
  }
});

Then('{string} should be active', function (label) {
  const li = findTodoItem.call(this, label);
  if (!li) throw new Error(`Todo "${label}" not found`);
  if (li.classList.contains('completed')) {
    throw new Error(`Expected "${label}" to be active, but it was completed`);
  }
});

Then('the todo count should say {string}', function (expected) {
  const el = this.document.querySelector('.todo-count');
  if (!el) throw new Error('Todo count element not found');
  const text = el.textContent.trim().replace(/\s+/g, ' ');
  if (text !== expected) {
    throw new Error(`Expected todo count "${expected}", got "${text}"`);
  }
});

Then('the clear completed button should not be visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn && btn.style.display !== 'none' && !btn.hidden) {
    throw new Error('Expected clear completed button to be hidden');
  }
});

Then('the clear completed button should be visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn || btn.style.display === 'none' || btn.hidden) {
    throw new Error('Expected clear completed button to be visible');
  }
});

Then('the toggle-all checkbox should be checked', function () {
  const toggle = this.document.querySelector('.toggle-all');
  if (!toggle) throw new Error('Toggle-all checkbox not found');
  if (!toggle.checked) {
    throw new Error('Expected toggle-all checkbox to be checked');
  }
});

Then('the toggle-all checkbox should not be checked', function () {
  const toggle = this.document.querySelector('.toggle-all');
  if (!toggle) throw new Error('Toggle-all checkbox not found');
  if (toggle.checked) {
    throw new Error('Expected toggle-all checkbox to not be checked');
  }
});

Then('the {string} filter link should have the selected class', function (label) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === label) {
      if (!a.classList.contains('selected')) {
        throw new Error(`Expected "${label}" filter link to have "selected" class`);
      }
      return;
    }
  }
  throw new Error(`Filter link "${label}" not found`);
});

Then('the {string} filter link should not have the selected class', function (label) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === label) {
      if (a.classList.contains('selected')) {
        throw new Error(`Expected "${label}" filter link to not have "selected" class`);
      }
      return;
    }
  }
  throw new Error(`Filter link "${label}" not found`);
});

Then('the localStorage should contain a todo with title {string}', function (title) {
  const data = this.localStorage.getItem(STORAGE_KEY);
  if (!data) throw new Error('localStorage has no todos data');
  const todos = JSON.parse(data);
  const found = todos.find(t => t.title === title);
  if (!found) throw new Error(`localStorage does not contain a todo with title "${title}"`);
});

Then('each todo in localStorage should have the keys {string}, {string}, and {string}', function (k1, k2, k3) {
  const data = this.localStorage.getItem(STORAGE_KEY);
  if (!data) throw new Error('localStorage has no todos data');
  const todos = JSON.parse(data);
  if (!Array.isArray(todos)) throw new Error('localStorage data is not an array');
  for (const todo of todos) {
    if (!(k1 in todo)) throw new Error(`Todo missing key "${k1}": ${JSON.stringify(todo)}`);
    if (!(k2 in todo)) throw new Error(`Todo missing key "${k2}": ${JSON.stringify(todo)}`);
    if (!(k3 in todo)) throw new Error(`Todo missing key "${k3}": ${JSON.stringify(todo)}`);
  }
});

Then('the localStorage key should be {string}', function (expectedKey) {
  const data = this.localStorage.getItem(expectedKey);
  if (data === null) {
    throw new Error(`localStorage key "${expectedKey}" not found`);
  }
  // Check that no other todo keys exist
  const len = this.localStorage.length;
  for (let i = 0; i < len; i++) {
    const key = this.localStorage.key(i);
    if (key !== expectedKey && key.startsWith('todos-')) {
      // Allow other keys, but flag if they look like todo storage
    }
  }
});

Then('the todo should not be in editing mode', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (editing) {
    throw new Error('Expected no todo to be in editing mode, but one is');
  }
});

Then('the localStorage should not contain the editing state', function () {
  const data = this.localStorage.getItem(STORAGE_KEY);
  if (!data) return; // no todos, nothing to check
  const todos = JSON.parse(data);
  for (const todo of todos) {
    if ('editing' in todo) {
      throw new Error(`localStorage contains an "editing" key on a todo`);
    }
  }
});

Then('I should see only active todos', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    if (li.classList.contains('completed')) {
      throw new Error('Expected no completed todos, but found one');
    }
  }
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
