function render() {
  var filtered = getFilteredTodos();

  // Build a map of existing list-item elements by data-id
  var existing = {};
  var children = Array.prototype.slice.call(todoList.children);
  for (var ci = 0; ci < children.length; ci++) {
    var child = children[ci];
    existing[child.getAttribute('data-id')] = child;
  }

  var handled = {};

  for (var i = 0; i < filtered.length; i++) {
    var todo = filtered[i];
    var li = existing[todo.id];

    if (li) {
      // Update existing element in place — preserves DOM references
      var cls = (todo.completed ? 'completed' : '') + ' ' + (todo.id === editingId ? 'editing' : '');
      li.className = cls;
      var toggle = li.querySelector('.toggle');
      toggle.checked = todo.completed;
      var label = li.querySelector('label');
      label.textContent = todo.title;
      var edit = li.querySelector('.edit');
      edit.value = todo.title;
      // Move to the correct position if the filtered order changed
      if (todoList.children[i] !== li) {
        todoList.insertBefore(li, todoList.children[i]);
      }
    } else {
      // Create a new element
      li = document.createElement('li');
      li.setAttribute('data-id', todo.id);
      li.className = (todo.completed ? 'completed' : '') + ' ' + (todo.id === editingId ? 'editing' : '');
      li.innerHTML = '<div class="view">' +
        '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>' +
        '<label>' + escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button></div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      if (i < todoList.children.length) {
        todoList.insertBefore(li, todoList.children[i]);
      } else {
        todoList.appendChild(li);
      }
    }

    handled[todo.id] = true;
  }

  // Remove elements for items no longer in the filtered list
  for (var id in existing) {
    if (!handled[id]) {
      existing[id].parentNode.removeChild(existing[id]);
    }
  }

